/**
 * The route registry: the single list of screens in the app.
 *
 * Every feature lives in `src/features/<dir>/index.tsx` and default-exports a React component that
 * receives `RouteProps`. Features are lazy-loaded, so a broken or heavy feature never blocks another.
 * Features do not edit this file; the shell reads it to build navigation, hubs and search.
 */
import type { ComponentType } from 'react';

export interface RouteProps {
  /** Slug-safe params after the route name: `#play--greensleeves` -> ["greensleeves"]. */
  params: string[];
}

export type Section = 'home' | 'learn' | 'play' | 'tools' | 'me';

export interface RouteDef {
  name: string;
  title: string;
  /** One line shown on hub cards and in search. */
  blurb: string;
  section: Section;
  /** lucide-react icon name (PascalCase). */
  icon: string;
  /** Shown as a card in its section hub. Detail routes (lesson runner, player) are hidden. */
  inHub: boolean;
  /** Needs the microphone / camera. The shell badges these when the host blocks the device. */
  needs?: Array<'mic' | 'camera'>;
  load: () => Promise<{ default: ComponentType<RouteProps> }>;
}

