export const ROUTE_BY_NAME: Record<string, RouteDef> = Object.fromEntries(ROUTES.map((r) => [r.name, r]));

export function routeDef(name: string): RouteDef {
  return ROUTE_BY_NAME[name] ?? ROUTE_BY_NAME.home;
}
